"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[97898],{51800:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"LoadingScreen","desc":"Replaces the default Roblox loading screen and covers the view until\\n`PreloadLib` has loaded every sound, animation, and texture/material the\\nclient can see.\\n\\nAssets come from two sources:\\n- Instances of `PRELOAD_CLASSES` under the replicated services (MeshParts\\n  give only their TextureID, so their meshes still stream in during play).\\n- Every `rbxassetid://` string inside the `Configs` modules (ids that only\\n  exist in code, such as SoundConfig SFX or TrainConfig animations), each\\n  wrapped in a Sound, Animation, or ImageLabel carrier.\\n\\nIt also warms every VFX texture: one idle emitter per unique\\nParticleEmitter/Beam/Trail texture stays parked on `workspace.Terrain`\\nfor the whole session (see `warmVfx`).\\n\\nThe bar counts batches, not PreloadLib\'s per-asset `completed`: one\\ninstance can resolve several assets or none. It never stands still: it\\ncreeps toward JOIN_END while the place downloads (Roblox gives no progress\\nfor that). The look: a star field, the title, and the pixel-art Aureline\\ntrain flying along a pixel rail; the rail behind the train turns amber as\\nthe bar fills. The rail scrolls, the train bobs, and its gears and thruster\\njets animate from a 4-frame sprite sheet. Art source:\\n`roblox-gui-prototypes/assets/loading-train.px.js`.","realm":["Client"],"source":{"line":30,"path":"src/ReplicatedFirst/LoadingScreen.client.luau"}}')}}]);